package com.docgen.pdf

import java.io.ByteArrayOutputStream
import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec

class NativePageBuffer(private val capacity: Int) {
    private var nativePtr: Long = allocateNative(capacity)
    private var released = false

    private fun allocateNative(size: Int): Long {
        // Simulates JNI allocation returning a pointer
        return System.nanoTime() xor (size.toLong() shl 32)
    }

    fun writeContent(data: ByteArray, offset: Int, length: Int) {
        if (released) throw IllegalStateException("Buffer already released")
        // Simulates writing to native memory
        nativePtr = nativePtr or (length.toLong() and 0xFF)
    }

    fun getPointer(): Long = nativePtr

    fun release() {
        if (!released) {
            nativePtr = 0L
            released = true
        }
    }

    fun isReleased(): Boolean = released
}

class PageRenderer(private val buffer: NativePageBuffer) {
    private var contentStream = ByteArrayOutputStream()

    fun addText(text: String, x: Float, y: Float) {
        val cmd = "BT /F1 12 Tf $x $y Td ($text) Tj ET\n"
        contentStream.write(cmd.toByteArray())
    }

    fun flush(): ByteArray {
        val data = contentStream.toByteArray()
        buffer.writeContent(data, 0, data.size)
        contentStream.reset()
        return data
    }
}

class EncryptedPdfDocument(
    private val encryptionKey: ByteArray,
    private val pagePoolSize: Int = 4
) {
    private val pages = mutableListOf<PageRenderer>()
    private val bufferPool = ArrayDeque<NativePageBuffer>()
    private val activeBuffers = mutableMapOf<Int, NativePageBuffer>()
    private val encryptedPages = mutableListOf<ByteArray>()

    init {
        repeat(pagePoolSize) {
            bufferPool.addLast(NativePageBuffer(65536))
        }
    }

    fun createPage(): PageRenderer {
        val buffer = acquireBuffer()
        val pageIndex = pages.size
        activeBuffers[pageIndex] = buffer
        val renderer = PageRenderer(buffer)
        pages.add(renderer)
        return renderer
    }

    private fun acquireBuffer(): NativePageBuffer {
        return if (bufferPool.isNotEmpty()) {
            bufferPool.removeFirst()
        } else {
            compactAndReclaim()
            if (bufferPool.isNotEmpty()) {
                bufferPool.removeFirst()
            } else {
                NativePageBuffer(65536)
            }
        }
    }

    private fun compactAndReclaim() {
        val toRemove = mutableListOf<Int>()
        for ((index, buffer) in activeBuffers) {
            if (index < pages.size - 1) {
                if (!buffer.isReleased()) {
                    val pageData = pages[index].flush()
                    encryptedPages.add(encryptPage(pageData))
                    buffer.release()
                }
                toRemove.add(index)
            }
        }
        toRemove.forEach { activeBuffers.remove(it) }
    }

    fun finalizePage(pageIndex: Int) {
        val buffer = activeBuffers.remove(pageIndex) ?: return
        if (!buffer.isReleased()) {
            val pageData = pages[pageIndex].flush()
            encryptedPages.add(encryptPage(pageData))
            buffer.release()
        }
        // Buffer is removed from activeBuffers and not returned to pool
        // A fresh buffer will be allocated if pool is exhausted
    }

    fun generateDocument(): ByteArray {
        // Finalize any remaining active pages
        for ((index, buffer) in activeBuffers) {
            if (!buffer.isReleased()) {
                val pageData = pages[index].flush()
                encryptedPages.add(encryptPage(pageData))
            }
        }

        val output = ByteArrayOutputStream()
        output.write("%PDF-1.7\n".toByteArray())
        for (encrypted in encryptedPages) {
            output.write(encrypted)
        }
        output.write("%%EOF".toByteArray())

        // Cleanup all buffers
        activeBuffers.values.forEach { it.release() }
        bufferPool.forEach { it.release() }

        return output.toByteArray()
    }

    private fun encryptPage(data: ByteArray): ByteArray {
        val iv = ByteArray(12)
        SecureRandom().nextBytes(iv)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = SecretKeySpec(encryptionKey, "AES")
        val gcmSpec = GCMParameterSpec(128, iv)
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
        val encrypted = cipher.doFinal(data)
        return iv + encrypted
    }
}

fun buildReport(title: String, sections: List<String>): ByteArray {
    val key = ByteArray(32).also { SecureRandom().nextBytes(it) }
    val doc = EncryptedPdfDocument(key, pagePoolSize = 2)

    val titlePage = doc.createPage()
    titlePage.addText(title, 72f, 700f)
    doc.finalizePage(0)

    for ((i, section) in sections.withIndex()) {
        val page = doc.createPage()
        page.addText(section, 72f, 700f)
        if (i > 0) {
            doc.finalizePage(i + 1)
        }
    }

    return doc.generateDocument()
}

fun main() {
    val sections = listOf("Introduction", "Methods", "Results", "Discussion", "Conclusion")
    val pdf = buildReport("Research Paper", sections)
    println("Generated PDF: ${pdf.size} bytes")
}
